// Read-only exact identity/member audit; no extraction, SDK or acceptance of native work.
import fs from 'node:fs';import zlib from 'node:zlib';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {readShards} from './shards.mjs';
const root=new URL('.',import.meta.url).pathname,sha=b=>crypto.createHash('sha256').update(b).digest('hex'),shards=readShards(),map=new Map(),blobs=new Map();let members=0,rawBytes=0,authorityFaults=0;
for(const r of shards){assert(!map.has(r.name));map.set(r.name,r.bytes);const v=JSON.parse(zlib.gunzipSync(r.bytes));for(const[h,text]of Object.entries(v.newBlobs)){const b=Buffer.from(text);assert.equal(sha(b),h);if(blobs.has(h))assert(blobs.get(h).equals(b));blobs.set(h,b);}}
for(const r of shards){const v=JSON.parse(zlib.gunzipSync(r.bytes));for(const f of v.files){const b=blobs.get(f.sha256);assert(b);assert.equal(b.length,f.bytes);assert.equal(sha(b),f.sha256);members++;rawBytes+=b.length;}for(const t of v.trace)if(t.kind.startsWith('R6-owned-authority')){assert(Buffer.from(t.before,'base64').equals(fs.readFileSync(root+'fixture-authority.txt')));assert(!Buffer.from(t.after,'base64').equals(Buffer.from(t.before,'base64')));authorityFaults++;}}
assert.equal(fs.readFileSync(root+'fixture-authority.txt','utf8'),'SYNTHETIC HOST FIXTURE ONLY; NOT A REAL EPOCH OR ACTUAL78 AUTHORITY\n');
const final=JSON.parse(fs.readFileSync(root+'resumed-final-green.json'));for(const[name,key]of [['guarded.mjs','sourceSha256'],['final-suite.mjs','suiteSha256'],['fixtures.mjs','fixtureSha256'],['focused-cases.mjs','focusedCasesSha256'],['budget.mjs','budgetSha256'],['final-guard-cases.mjs','finalGuardCasesSha256'],['shards.mjs','shardsSha256']])assert.equal(sha(fs.readFileSync(root+name)),final[key]);assert.equal(final.results.length,63);assert(final.budget.maximumReservedProjection<=1048576);for(const r of final.results){assert.equal(r.status,'PASS');assert.equal(sha(map.get(r.custody.shard)),r.custody.sha256);}
for(const[name,status]of [['resumed-predecessor-red.json','FAIL'],['resumed-targeted-green.json','PASS']]){const r=JSON.parse(fs.readFileSync(root+name));assert.equal(r.results.length,11);for(const x of r.results){assert.equal(x.status,status);assert.equal(sha(map.get(x.custody.shard)),x.custody.sha256);}}
const patch=JSON.parse(fs.readFileSync(root+'repair.json'));let code=fs.readFileSync('/tmp/r4-wire-guarded-command-custody-boundary-successor-20261023/guarded.mjs','utf8');assert.equal(sha(code),patch.beforeSha256);for(const p of patch.patches){assert.equal(code.split(p.from).length,2);code=code.replace(p.from,p.to);}assert.equal(sha(code),patch.afterSha256);assert.equal(code,fs.readFileSync(root+'guarded.mjs','utf8'));const epoch=JSON.parse(fs.readFileSync(root+'USER-RESUME-EPOCH.json'));assert.equal(sha(fs.readFileSync(root+'budget-before-user-resume.mjs')),epoch.oldGateSha256);assert.equal(sha(fs.readFileSync(root+'budget.mjs')),epoch.newGateSha256);assert.equal(fs.readFileSync(root+'predecessor-red.json').length,0);
console.log(JSON.stringify({status:'PASS_READ_ONLY_EXACT_HOST_CUSTODY',shards:shards.length,rawMembers:members,rawBytes,authorityFaultTraces:authorityFaults,ownedAuthorityRestored:true,predecessorActualReds:11,targetedSuccessorGreen:11,finalExactSourceGreen:63,patchReconstruction:'EXACT',priorStorageHold:'PRESERVED_BEFORE_ANY_CASE',userDirectedBudgetEpoch:'EXACT_OLD_AND_NEW_SOURCE_PINS',budget:final.budget,storage:final.storage,proofAcceptance:false},null,2));

import fs from 'node:fs';import assert from 'node:assert/strict';
export const packet=new URL('.',import.meta.url).pathname.replace(/\/$/,''),observations=[];export function allocated(){const seen=new Set();let n=0;function walk(p){const s=fs.lstatSync(p),k=s.dev+':'+s.ino;if(!seen.has(k)){seen.add(k);n+=s.blocks*512;}if(s.isDirectory())for(const x of fs.readdirSync(p))walk(p+'/'+x);}walk(packet);return n;}
export function gate(label,extra=0){const current=allocated(),reserve=Math.ceil(extra/4096)*4096+65536;assert(current+reserve<=1048576,`Aggregate budget ${label}: ${current}+${reserve}>1048576`);observations.push({label,allocated:current,reserved:reserve});return current;}
export function phase(name,extra){const s=fs.statfsSync('/Users/casey.allard',{bigint:true}),free=Number(s.bavail*s.bsize/1024n);assert(free>=10486784&&38350308-free<=2097152,'Host storage phase gate');gate('phase:'+name,extra);return{freeKiB:free,baselineKiB:38350308,allocated:allocated(),reservedExtra:extra,outputReserve:65536};}

import fs from 'node:fs';import assert from 'node:assert/strict';
export const packet=new URL('.',import.meta.url).pathname.replace(/\/$/,''),observations=[];export function allocated(){const seen=new Set();let n=0;function walk(p){const s=fs.lstatSync(p),k=s.dev+':'+s.ino;if(!seen.has(k)){seen.add(k);n+=s.blocks*512;}if(s.isDirectory())for(const x of fs.readdirSync(p))walk(p+'/'+x);}walk(packet);return n;}
export function gate(label,extra=0){const current=allocated(),reserve=Math.ceil(extra/4096)*4096+65536;assert(current+reserve<=1048576,`Aggregate budget ${label}: ${current}+${reserve}>1048576`);observations.push({label,allocated:current,reserved:reserve});return current;}
export function phase(name,extra){const s=fs.statfsSync('/Users/casey.allard',{bigint:true}),free=Number(s.bavail*s.bsize/1024n);assert(free>=10486784,'Host reserve gate');const previous=observations.filter(x=>x.freeKiB!==undefined).at(-1)?.freeKiB??28079568;observations.push({label:'storage:'+name,allocated:allocated(),reserved:0,freeKiB:free,baselineKiB:28079568,previousFreeKiB:previous,monitorInvestigateReport:28079568-free>2097152||previous-free>2097152});gate('phase:'+name,extra);return{freeKiB:free,baselineKiB:28079568,allocated:allocated(),reservedExtra:extra,outputReserve:65536};}

import fs from 'node:fs';import assert from 'node:assert/strict';import {gate,packet} from './budget.mjs';
export function finalGuardCases({call}){const rows=[];function add(name,body,verb){rows.push({group:'CODE_R5_R6',name,body,reserve:verb==='verify'?570:330});}
for(const verb of ['check','verify'])for(const boundary of ['observer','await','pins'])add('R5-current-pre-extra-'+verb+'-'+boundary,async f=>{const prior=verb==='verify'?await call(f):undefined;let inserted=false,armed=false;const addLeaf=()=>{if(!inserted){gate('owned-current-pre-extra',4096);fs.writeFileSync(f.work+'/'+verb+'/pre/source/extra.json','{}',{flag:'wx'});inserted=true;}};const observe=f.effects.observe;f.effects.observe=event=>{observe(event);if(event==='formal.attempted'){armed=true;if(boundary==='observer')addLeaf();}};if(boundary==='pins'){const pins=f.effects.pins;f.effects.pins=()=>{pins();if(armed)addLeaf();};}if(boundary==='await'){const persist=f.effects.persist;f.effects.persist=async(...args)=>{await persist(...args);if(args[1]===verb+'/pre/storage/host-completion.json')addLeaf();};}let threw=false,error,result;try{result=await call(f,verb,prior);}catch(e){threw=true;error=e;}const dispatched=f.trace.some(x=>x.kind==='dispatch'&&x.label===verb+'/command');f.trace.push({kind:'R5-observation',verb,boundary,inserted,threw,returned:result?.status??null,formalDispatched:dispatched});assert(inserted,'Hook reached');assert(threw,'Extra preguard file must reject');assert(!dispatched,'Extra current preguard leaf must block formal dispatch');assert.equal(error.formalAttempted,false);assert(f.trace.some(x=>x.kind==='dispatch'&&x.label===verb+'/post/idle'));},verb);
for(const verb of ['check','verify'])for(const boundary of ['dispatch','issuance'])add('R6-owned-dependency-'+verb+'-'+boundary,async f=>{const prior=verb==='verify'?await call(f):undefined;const dep=packet+'/fixture-authority.txt',before=fs.readFileSync(dep);let inserted=false,armed=false;const observe=f.effects.observe;f.effects.observe=e=>{observe(e);if(e==='formal.attempted')armed=true;};const pins=f.effects.pins;f.effects.pins=()=>{pins();if(!inserted&&(boundary==='dispatch'?armed:fs.existsSync(f.work+'/'+verb+'/closure.json'))){gate('owned-fixture-authority-drift',4096);fs.appendFileSync(dep,' owned boundary drift');inserted=true;}};let threw=false,error,result;try{try{result=await call(f,verb,prior);}catch(e){threw=true;error=e;}const after=fs.readFileSync(dep);f.trace.push({kind:'R6-owned-authority-observation',verb,boundary,inserted,threw,returned:result?.status??null,formalAttempted:error?.formalAttempted??null,before:before.toString('base64'),after:after.toString('base64')});assert(inserted,'Hook reached');assert(threw,'Final dependency drift must reject result');if(boundary==='dispatch'){assert.equal(error.formalAttempted,false,'Dependency drift must block formal recorder attempt, even if recorder has a later guard');assert(!f.trace.some(x=>x.kind==='dispatch'&&x.label===verb+'/command'));}}finally{fs.writeFileSync(dep,before);assert(fs.readFileSync(dep).equals(before));}},verb);
add('R6-owned-dependency-prior-reconstruction',async f=>{const prior=await call(f),dep=packet+'/fixture-authority.txt',before=fs.readFileSync(dep),start=f.trace.length;let count=0,inserted=false;const pins=f.effects.pins;f.effects.pins=()=>{pins();if(++count===3){gate('owned-fixture-authority-drift',4096);fs.appendFileSync(dep,' owned prior-reconstruction drift');inserted=true;}};let threw=false;try{try{await call(f,'verify',prior);}catch{threw=true;}f.trace.push({kind:'R6-owned-authority-reconstruction',inserted,threw,before:before.toString('base64'),after:fs.readFileSync(dep).toString('base64')});assert(inserted);assert(threw);assert(!f.trace.slice(start).some(x=>x.kind==='observe'&&x.label==='pre.source.paths.capture'),'Dependency drift must reject before starting verify pre-capture');}finally{fs.writeFileSync(dep,before);assert(fs.readFileSync(dep).equals(before));}},'verify');
return rows;}

import fs from 'node:fs';import assert from 'node:assert/strict';import {fixture,sealAndReclaim,packet,ctx,root,sha} from './fixtures.mjs';import {observations,allocated,gate} from './budget.mjs';import {cases} from './focused-cases.mjs';import {finalGuardCases} from './final-guard-cases.mjs';import * as g from './guarded.mjs';
const run=process.argv[2];assert(run);const results=[],queue=[],flat=e=>e instanceof AggregateError?e.errors.flatMap(flat):[e];const call=(f,verb='check',priorCheck)=>g.guardedCommand({ctx:f.ctx,root:f.root,binding:f.binding,owner:f.owner,label:verb,verb,effects:f.effects,priorCheck});async function rejected(fn){let threw=false,error;try{await fn();}catch(e){threw=true;error=e;}assert(threw,'Expected failure');return error;}async function reject(f,verb='check',prior){return rejected(()=>call(f,verb,prior));}async function groupTest(group,name,body,mutate){queue.push({group,name,body,mutate});}async function refineTest(name,body,mutate){queue.push({group:'R1_R2',name,body,mutate});}
await groupTest(1,'null-live-and-forged-input',async f=>{assert.throws(()=>g.executionPrerequisite());const e=await g.guardedCommand({ctx:{...ctx},root,binding:f.binding,owner:f.owner,label:'check',verb:'check',effects:f.effects}).then(()=>null,e=>e);assert(e);assert(!f.trace.some(x=>x.kind==='dispatch'));});
await groupTest(2,'complete-check-verify',async f=>{const check=await call(f),verify=await call(f,'verify',check);assert.equal(check.verb,'check');assert.equal(verify.verb,'verify');assert.equal(verify.proofAcceptance,false);assert.equal(verify.semanticAcceptance,false);assert(f.trace.filter(x=>x.kind==='dispatch'&&x.label.endsWith('/command')).length===2);assert.equal(verify.checkContextId,ctx.contextId);});
await groupTest(3,'forged-check-rejected',async f=>{const e=await reject(f,'verify',{status:'PASS',contextId:ctx.contextId});assert(e);assert(!f.trace.some(x=>x.kind==='dispatch'&&x.label.endsWith('/command')));});
await groupTest(3,'stale-check-rejected',async f=>{const check=await call(f);fs.appendFileSync(f.work+'/check/post/source/links/stdout','x');const e=await reject(f,'verify',check);assert(e);assert(!f.trace.some(x=>x.kind==='dispatch'&&x.label==='verify/command'));});
await groupTest(4,'primary-falsey-posts',async f=>{const e=await reject(f);assert(flat(e).includes(false));for(const part of ['memory','epoch/boot','source/hashes','sdk/tools','storage/guest','idle'])assert(f.trace.some(x=>x.kind==='dispatch'&&x.label==='check/post/'+part),part);},(kind,label)=>{if(kind==='dispatch'&&label==='check/command')throw false;});
await groupTest(4,'invalid-command-json',async f=>{const e=await reject(f);assert(e);assert(f.trace.some(x=>x.label==='check/post/idle'&&x.kind==='dispatch'));},(kind,label)=>kind==='payload'&&label==='check/command'?{text:'broken-json'}:null);
await groupTest(5,'source-sibling-errors',async f=>{const e=await reject(f);const text=flat(e).map(String).join('\n');assert(text.includes('links'));assert(text.includes('hashes'));assert(!f.trace.some(x=>x.label==='check/command'&&x.kind==='dispatch'));},(kind,label)=>{if(kind==='dispatch'&&label==='check/pre/source/paths')throw Error('missing paths');if(kind==='payload'&&label==='check/pre/source/links')return{text:'BAD_LINK'};if(kind==='payload'&&label==='check/pre/source/hashes')return{text:'BAD_HASH'};});
await groupTest(5,'sdk-epoch-sibling-errors',async f=>{const e=await reject(f);for(const term of ['sdk.inspect.payload','sdk.executable.payload','sdk.tools.payload','epoch.inspect.payload','epoch.boot.payload'])assert(e.phases.some(p=>p.includes(term)),term);},(kind,label)=>{if(kind==='payload'&&['check/post/sdk/inspect','check/post/sdk/executable','check/post/sdk/tools','check/post/epoch/inspect','check/post/epoch/boot'].includes(label))return{text:'MALFORMED'};});
await groupTest(5,'host-failure-guest-inspected',async f=>{const e=await reject(f);assert(flat(e).includes(null));assert(f.trace.some(x=>x.label==='check/post/storage/guest'&&x.kind==='dispatch'));assert(f.trace.some(x=>x.kind==='observe'&&x.label.includes('guest.payload')));},(kind,label)=>{if(kind==='statfs')throw null;if(kind==='payload'&&label.endsWith('/storage/guest'))return{text:'bad-df'};});
await groupTest(6,'guest-threshold',async f=>{const e=await reject(f);assert(flat(e).some(x=>String(x).includes('reserve')));},(kind,label)=>kind==='payload'&&label==='check/pre/storage/guest'?{text:'Filesystem 1024-blocks Used Available Capacity Mounted on\n/dev/sda 99999999 1 10485760 1% /\n'}:null);
await groupTest(6,'host-bigint-exact',async f=>{await call(f);const host=JSON.parse(fs.readFileSync(f.work+'/check/pre/storage/host-observation.json'));assert.equal(host.availableBytes,String(4096n*2251799813685249n));},kind=>kind==='statfs'?{type:1n,bsize:4096n,bavail:2251799813685249n}:null);
await groupTest(6,'epoch-and-counter-change',async f=>{const e=await reject(f);assert(e);assert(f.trace.some(x=>x.kind==='observe'&&x.label.includes('post.epoch.boot.payload')));},(kind,label)=>kind==='payload'&&label==='check/post/memory'?{text:'oom 1\noom_kill 0\noom_group_kill 0\n'}:kind==='payload'&&label==='check/post/epoch/boot'?{text:'different-boot'}:null);
await groupTest(7,'await-completion-persistence',async f=>{let release,entered;const waiting=new Promise(r=>entered=r),deferred=new Promise(r=>release=r);const original=f.effects.persist;f.effects.persist=async(...args)=>{if(args[1]==='check/post/storage/host-completion.json'){entered();await deferred;}return original(...args);};let done=false;const pending=call(f).then(x=>{done=true;return x;});await waiting;assert.equal(done,false);release();const check=await pending;await call(f,'verify',check);});
await groupTest(7,'valid-looking-failed-check-not-reusable',async f=>{const e=await reject(f);assert(flat(e).includes(false));const fake={verb:'check',contextId:ctx.contextId};await reject(f,'verify',fake);assert(!f.trace.some(x=>x.kind==='dispatch'&&x.label==='verify/command'));},(kind,label)=>{if(kind==='persist.done'&&label==='check/post/storage/host-completion.json')throw false;});
await groupTest(7,'final-raw-drift',async f=>{const persist=f.effects.persist;f.effects.persist=async(...args)=>{await persist(...args);if(args[1]==='check/closure.json')fs.appendFileSync(f.work+'/check/post/source/links/stdout','drift');};await reject(f);});
await groupTest(8,'resource-not-negative',async f=>{await reject(f);},(kind,label)=>kind==='payload'&&label==='check/command'?{stderr:'timeout'}:null);
await groupTest(8,'context-census-mismatch',async f=>{const l=await import('/tmp/r4-hash-wire-awaited-cleanup-implementation-20261023/library.mjs');f.ctx=l.context('projected');f.root=l.rootFor(f.ctx,root.module);await reject(f);assert(!f.trace.some(x=>x.kind==='dispatch'&&x.label==='check/command'));});
await refineTest('closure-falsey-owned-error',async f=>{const persist=f.effects.persist;f.effects.persist=async(...args)=>{await persist(...args);if(args[1]==='check/closure.json')throw null;};const e=await rejected(()=>call(f));assert(e instanceof AggregateError,'Closure failure must retain typed ordered aggregate');assert(flat(e).includes(null));assert(e.phases.includes('closure.persist'));assert(JSON.parse(fs.readFileSync(f.work+'/check/closure.json')));await rejected(()=>call(f,'verify',{verb:'check',contextId:ctx.contextId}));});
await refineTest('observer-failure-keeps-posts',async f=>{const e=await rejected(()=>call(f));assert(flat(e).includes(undefined));assert(f.trace.some(x=>x.kind==='dispatch'&&x.label==='check/post/idle'));},(kind,label)=>{if(kind==='observe'&&label==='post.memory.capture-group')throw undefined;});
await refineTest('verify-recorder-failure-keeps-posts',async f=>{const check=await call(f);const e=await rejected(()=>call(f,'verify',check));assert(flat(e).includes(0));for(const part of ['memory','epoch/boot','source/hashes','sdk/tools','storage/guest','idle'])assert(f.trace.some(x=>x.kind==='dispatch'&&x.label==='verify/post/'+part),part);},(kind,label)=>{if(kind==='dispatch'&&label==='verify/command')throw 0;});
for(const when of ['start','end','completed'])await refineTest('host-clock-'+when,async f=>{const e=await rejected(()=>call(f));assert(flat(e).includes(false));assert(f.trace.some(x=>x.kind==='dispatch'&&x.label==='check/pre/storage/guest'));assert(f.trace.some(x=>x.kind==='observe'&&x.label==='pre.storage.guest.payload'));},(kind,label)=>{if(kind==='clock'&&label==='pre.storage.host.'+when)throw false;});
await refineTest('host-statfs-and-end-errors',async f=>{const e=await rejected(()=>call(f));assert(flat(e).includes(null));assert(flat(e).includes(0));assert(e.phases.indexOf('pre.storage.host.statfs')<e.phases.indexOf('pre.storage.host.end'));},(kind,label)=>{if(kind==='statfs')throw null;if(kind==='clock'&&label==='pre.storage.host.end')throw 0;});
await refineTest('sample-write-then-throw',async f=>{const persist=f.effects.persist;f.effects.persist=async(...args)=>{await persist(...args);if(args[1]==='check/pre/storage/host-observation.json')throw false;};const e=await rejected(()=>call(f));assert(flat(e).includes(false));assert(JSON.parse(fs.readFileSync(f.work+'/check/pre/storage/host-observation.json')));assert(f.trace.some(x=>x.kind==='dispatch'&&x.label==='check/pre/storage/guest'));});
await refineTest('sample-readback-corruption',async f=>{const persist=f.effects.persist;f.effects.persist=async(...args)=>{await persist(...args);if(args[1]==='check/pre/storage/host-observation.json')fs.appendFileSync(f.work+'/'+args[1],'x');};await rejected(()=>call(f));assert(f.trace.some(x=>x.kind==='dispatch'&&x.label==='check/pre/storage/guest'));});
await refineTest('completion-readback-corruption',async f=>{const persist=f.effects.persist;f.effects.persist=async(...args)=>{await persist(...args);if(args[1]==='check/post/storage/host-completion.json')fs.appendFileSync(f.work+'/'+args[1],'x');};await rejected(()=>call(f));assert(f.trace.some(x=>x.kind==='dispatch'&&x.label==='check/post/storage/guest'));});
for(const [name,sample]of [['nonbigint',{type:1n,bsize:4096,bavail:999999999n}],['negative',{type:1n,bsize:4096n,bavail:-1n}],['zero-size',{type:1n,bsize:0n,bavail:999999999n}]])await refineTest('host-'+name,async f=>{await rejected(()=>call(f));assert(f.trace.some(x=>x.kind==='dispatch'&&x.label==='check/pre/storage/guest'));},kind=>kind==='statfs'?sample:null);
await refineTest('host-identity-replaced',async f=>{const lstat=f.effects.lstatBig;let n=0;f.effects.lstatBig=p=>{const st=lstat(p);if(++n===2)return{dev:st.dev,ino:st.ino+1n,isDirectory:()=>true,isSymbolicLink:()=>false};return st;};await rejected(()=>call(f));assert(f.trace.some(x=>x.kind==='dispatch'&&x.label==='check/pre/storage/guest'));});
await refineTest('host-reversed-interval',async f=>{const now=f.effects.now;f.effects.now=label=>label==='pre.storage.host.end'?'2020-01-01T00:00:00.000Z':now(label);await rejected(()=>call(f));});
await refineTest('post-host-reserve',async f=>{let n=0;const stat=f.effects.statfs;f.effects.statfs=p=>++n===2?{type:1n,bsize:1n,bavail:10737418239n}:stat(p);const e=await rejected(()=>call(f));assert(flat(e).some(x=>String(x).includes('reserve')));});
await refineTest('post-guest-reserve',async f=>{const e=await rejected(()=>call(f));assert(flat(e).some(x=>String(x).includes('reserve')));},(kind,label)=>kind==='payload'&&label==='check/post/storage/guest'?{text:'Filesystem 1024-blocks Used Available Capacity Mounted on\n/dev/sda 99999999 1 10485759 1% /\n'}:null);
